const announceOn=()=>store.get('announce')==='on';
const keepAwake=()=>{try{native?.keepScreenOn?.(announceOn()&&!!st.token)}catch{}};
const tableWords=t=>{const n=Number(String(t||'').replace(/^T/i,''));return (n>0&&n<1000?n:String(t||''))+'号桌'};
const orderPhrase=o=>o.table==='TAKEAWAY'?'外带，有新订单':tableWords(o.table)+'，有新订单';
function chime(){if(native?.chime){native.chime();return}try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return;const ctx=announce.ctx||(announce.ctx=new C());if(ctx.state==='suspended'&&ctx.resume)ctx.resume();const t=ctx.currentTime;[[880,0],[660,0.3]].forEach(([f,d])=>{const o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.value=f;g.gain.setValueAtTime(0.0001,t+d);g.gain.exponentialRampToValueAtTime(0.7,t+d+0.02);g.gain.exponentialRampToValueAtTime(0.0001,t+d+0.5);o.connect(g);g.connect(ctx.destination);o.start(t+d);o.stop(t+d+0.55)})}catch{}}
function zhVoice(){try{const zh=(window.speechSynthesis?.getVoices?.()||[]).filter(v=>/^(zh|cmn)/i.test(v.lang||''));return zh.find(v=>/CN|Hans/i.test(v.lang)&&/natural|online/i.test(v.name))||zh.find(v=>/CN|Hans/i.test(v.lang))||zh[0]||null}catch{return null}}
function speakText(text){if(native?.speak)return native.speak(text)==='OK';const v=zhVoice();if(!v||typeof SpeechSynthesisUtterance==='undefined')return false;const u=new SpeechSynthesisUtterance(text);u.voice=v;u.lang=v.lang;u.rate=0.95;window.speechSynthesis.speak(u);return true}
function voiceStatus(){if(native?.ttsStatus){try{const x=JSON.parse(native.ttsStatus());if(x.state==='READY')return 'Đọc bằng giọng tiếng Trung của máy / 使用设备中文语音';if(x.state==='INIT')return 'Đang khởi động giọng đọc… / 语音启动中';return 'Máy chưa có giọng tiếng Trung: chỉ phát chuông. Cài "Speech Services by Google" và tải giọng 中文. / 未安装中文语音，仅响铃'}catch{}}if(native)return 'APK này chưa đọc được chữ: chỉ phát chuông; cập nhật APK. / 请更新 APK';const v=zhVoice();return v?'Giọng đọc / 语音: '+v.name:'Trình duyệt chưa có giọng tiếng Trung: chỉ phát chuông. / 浏览器无中文语音，仅响铃'}
function showAnnounce(text){try{const old=document.querySelector('#announce-toast');old?.remove();const el=document.createElement('div');el.id='announce-toast';el.setAttribute('role','status');el.textContent='🔔 '+text;document.body.appendChild(el);setTimeout(()=>{if(el.parentNode)el.remove()},9000)}catch{}}
function say(text){if(!announceOn())return;chime();showAnnounce(text);setTimeout(()=>{try{speakText(text)}catch{}},700)}
function unlockAudio(){if(announce.unlocked)return;announce.unlocked=true;try{const C=window.AudioContext||window.webkitAudioContext;if(C){announce.ctx=announce.ctx||new C();if(announce.ctx.resume)announce.ctx.resume()}}catch{}try{if(window.speechSynthesis&&typeof SpeechSynthesisUtterance!=='undefined'){const u=new SpeechSynthesisUtterance(' ');u.volume=0;window.speechSynthesis.speak(u)}}catch{}document.querySelector('#announce-unlock')?.remove()}
