function announceOrders(list){
 if(!Array.isArray(list)||!st.token)return;if(announce.token!==st.token){announce.token=st.token;announce.seen.clear();announce.seeded=false;announce.serviceSeeded=false}
 const fresh=list.filter(o=>o&&o.id&&!announce.seen.has(o.id));for(const o of list)if(o?.id)announce.seen.add(o.id);
 if(!announce.seeded){announce.seeded=true;return}// what was already there when the device opened is not announced
 const kitchen=kitchenOnly();
 for(const o of fresh){if(o.status==='CANCELLED'||(!kitchen&&o.source!=='QR'))continue;if(!(Date.now()-Date.parse(o.createdAt||'')<15*60000))continue;say(orderPhrase(o))}
}
