 return `<nav aria-label="Điều hướng POS">${counter?'<div class="nav-brand"><img src="/brands/phat-tai.png" alt="Logo TIỆM SÍU LẬP PHÁT TÀI" width="44" height="44"><span><strong>Lotus POS</strong><small>Cloud · Cửa hàng / 门店</small></span></div>':''}${visible.map(([key,label,,cn])=>counter&&key==='shifts'&&window.LotusShiftUI?`<div class="shift-nav"><button data-screen="shifts" class="${st.screen===key?'active':''}" aria-expanded="${st.shiftNavOpen}"><span>${label} <span aria-hidden="true">${st.shiftNavOpen?'▾':'▸'}</span></span><small>${cn}</small></button>${st.shiftNavOpen?window.LotusShiftUI.tabs.map(([k,icon,vi,zh])=>`<button class="shift-child ${st.screen==='shifts'&&st.shiftTab===k?'active':''}" data-shift-tab="${k}"><span>${icon} ${vi}</span><small>${zh}</small></button>`).join(''):''}</div>`:`<button data-screen="${key}" class="${on(key)?'active':''}" ${on(key)?'aria-current="page"':''}><span>${label}</span>${counter?`<small lang="zh-CN">${cn}</small>`:''}</button>`).join('')}${counter?'<div class="nav-footer">Dữ liệu đồng bộ Cloudflare D1<br><small>四个界面 · 一个数据库</small></div>':''}</nav>`;
