 const editor=`<div class="card"><h2>${p?'Sửa '+esc(p.sku):'Thêm mới / 新增'}</h2><form id="product-form" data-id="${esc(p?.id||'')}"><label>Mã món (không đổi sau khi tạo)</label><input name="id" value="${esc(p?.id||'')}" pattern="[A-Za-z0-9_\\-]{1,24}" ${p?'readonly':'required'}><label>SKU / Barcode</label><input name="sku" value="${esc(p?.sku||'')}" required><label>Tên món / 商品名称</label><input name="name" value="${esc(p?.name||'')}" required><label>Tên tiếng Trung</label><input name="nameCn" value="${esc(p?.nameCn||'')}"><label>Danh mục</label><input name="category" value="${esc(p?.category||'Cơm phần')}" required><label>Giá thường (đ)</label><input name="price" type="number" min="0" value="${p?.price??0}" required><label>Giá lớn (đ)</label><input name="largePrice" type="number" min="0" value="${p?.largePrice??0}" required><label>Trạm in bếp</label><select name="station"><option value="KITCHEN" ${p?.station!=='BAR'?'selected':''}>Bếp</option><option value="BAR" ${p?.station==='BAR'?'selected':''}>Quầy nước</option></select><label>Biểu tượng</label><input name="icon" value="${esc(p?.icon||'🍚')}" maxlength="8"><label class="perm"><input name="size" type="checkbox" ${p?.size?'checked':''}> Cho chọn phần lớn</label><label class="perm"><input name="spicy" type="checkbox" ${p?.spicy?'checked':''}> Cho chọn độ cay</label><label class="perm"><input name="active" type="checkbox" ${p?.active??true?'checked':''}> Đang bán</label>${p?`<p class="muted">Công thức đang dùng: ${esc(recipe||'không dùng nguyên liệu')}. Chỉ dùng để ước tính tiêu hao, không khóa bán.</p>`:`<label>Công thức lúc tạo (mỗi phần; tùy chọn)</label><textarea name="recipe" rows="2" placeholder="ING-RICE:250, ING-DUCK:100"></textarea><small>Nguyên liệu có trong Kho: ${esc(st.ingredients.map(x=>x.id+' ('+x.unit+')').join(', '))}</small>`}<div class="buttons"><button class="primary">${p?'Lưu món':'Tạo món'}</button>${p?'<button type="button" data-action="product-new">Tạo món khác</button>':''}</div></form></div>`