 const rows=st.products.map(x=>`<tr><td aria-label="Biểu tượng">${esc(x.icon)}</td><td>${esc(x.sku)}</td><td><strong>${esc(x.name)}</strong><br><small>${esc(x.nameCn)}</small></td><td>${esc(x.category)}</td><td>${fmt(x.price)}</td><td>${st.catalog.find(y=>y.id===x.id)?.stock??0}</td><td><span class="badge">${x.active?'Đang bán':'Ngưng bán'}</span></td><td><button data-edit-product="${esc(x.id)}">Sửa</button></td></tr>`).join('');
 const list=counter?`<div class="card"><div class="row"><h2>Sản phẩm / Dịch vụ · 商品 / 服务</h2><button data-action="product-new">+ Thêm mới</button></div><div class="table-wrap"><table class="poc-table"><thead><tr><th>Icon</th><th>SKU</th><th>Tên / 名称</th><th>Danh mục</th><th>Giá</th><th>Ghi sổ</th><th>Trạng thái</th><th></th></tr></thead><tbody>${rows||'<tr><td colspan="8">Chưa có món trên D1.</td></tr>'}</tbody></table></div></div>`:st.products.map(x=>`<div class="card row"><span>${esc(x.icon)} ${esc(x.sku)} · ${esc(x.name)} · ${fmt(x.price)} · ${x.active?'Đang bán':'Ngưng bán'} · ghi sổ ${st.catalog.find(y=>y.id===x.id)?.stock??0}</span><button data-edit-product="${esc(x.id)}">Sửa</button></div>`).join('');
 return `<h1>Sản phẩm trên D1 <button data-action="refresh">↻</button></h1><p class="muted">Giá sửa chỉ áp dụng đơn mới. Tồn nhập/kiểm kê chỉ để theo dõi; công thức trừ ước tính, không khóa bán trên QR hoặc POS.</p>${counter?`<div class="admin-grid">${list}${editor}</div>`:editor+list}`;
