   if(!editing&&!field('name').value.trim())throw Error('Nhập tên ca / 请输入班次名称');if(!(startTime<endTime))throw Error('Giờ ra phải sau giờ vào ('+startTime+' → '+endTime+') / 下班时间必须晚于上班时间');if(!staffIds.length)throw Error('Chọn ít nhất một nhân viên cho ca / 请至少选择一名员工');
   const body={name:field('name').value,startTime,endTime,staffIds,startsOn:field('startsOn').value};
   if(editing)await api('POST','/api/staff/fixed-shifts/'+encodeURIComponent(editing.id),{...body,version:editing.version});else await api('POST','/api/staff/fixed-shifts',body);
