const scheduler={
 live:{base:15000,max:120000,next:0,fail:0,running:false,pending:false,fn:syncLive},
 scanner:{base:2000,max:15000,next:0,fail:0,running:false,pending:false,fn:pollScanner},
 service:{base:8000,max:120000,next:0,fail:0,running:false,pending:false,fn:pollService},
 print:{base:3000,max:15000,next:0,fail:0,running:false,pending:false,fn:pollAutoPrint},
 announce:{base:15000,max:120000,next:0,fail:0,running:false,pending:false,fn:watchOrders}
};
function taskEnabled(name){if(document.hidden||!st.token)return false;if(name==='scanner')return counter;if(name==='service')return (counter||(!!native&&announceOn()&&!kitchenOnly()))&&can('ORDER_VIEW');if(name==='announce')return announceOn()&&can('ORDER_VIEW')&&!liveFetchesOrders();if(name==='print')return (counter||!!native)&&can('PRINT_KITCHEN');return true}
function taskBase(task){if(st.realtimeState!=='ONLINE')return task.base;return task===scheduler.print?10000:(task===scheduler.live||task===scheduler.service||task===scheduler.announce)?60000:task.base}
function taskDelay(task){return Math.min(task.max,taskBase(task)*Math.max(1,2**Math.min(task.fail,4)))}
function runScheduled(name,force=false){
 const task=scheduler[name],now=Date.now();if(!task||!taskEnabled(name))return;
 if(task.running){if(force)task.pending=true;return}
 if((!force||task.fail>0)&&now<task.next)return;
 task.running=true;task.next=now+taskDelay(task);
 return Promise.resolve().then(task.fn).then(()=>{task.fail=0;task.next=Date.now()+taskBase(task)}).catch(()=>{task.fail++;task.next=Date.now()+taskDelay(task)}).finally(()=>{
  task.running=false;const again=task.pending;task.pending=false;if(again&&!task.fail){task.next=0;runScheduled(name,true)}
 });
}
function schedulerTick(){if(rollDay()&&st.token&&['dashboard','shifts'].includes(st.screen))refresh();runScheduled('live');runScheduled('scanner');runScheduled('service');runScheduled('print');runScheduled('announce')}
const pendingScopes=new Set();let wakeTimer=null;
function wakeSync(scope='state',scopes=null){
 st.syncStats.realtime++;for(const x of scopes||[scope])pendingScopes.add(x);
 if(wakeTimer)return;
 wakeTimer=setTimeout(()=>{
  wakeTimer=null;const changed=new Set(pendingScopes);pendingScopes.clear();
  if(changed.has('state')||changed.has('staff')){runScheduled('live',true);runScheduled('service',true);runScheduled('print',true);runScheduled('announce',true);return}
  if([...changed].some(x=>x!=='print'&&x!=='service')||(changed.has('print')&&st.selected))runScheduled('live',true);
  if(changed.has('orders'))runScheduled('announce',true);
  if(changed.has('service'))runScheduled('service',true);
  if(changed.has('print'))runScheduled('print',true);
 },150);
}
const realtime={ws:null,timer:null,retry:1000,ping:null,stopped:true,lastPong:0};
function realtimeBase(){try{const base=native?.getCloudBase?.();if(base)return base}catch{}return /^https?:$/.test(location.protocol)?location.origin:null}
function closeRealtime(){
 realtime.stopped=true;if(realtime.timer){clearTimeout(realtime.timer);realtime.timer=null}if(realtime.ping){clearInterval(realtime.ping);realtime.ping=null}
 if(wakeTimer){clearTimeout(wakeTimer);wakeTimer=null}pendingScopes.clear();
 const ws=realtime.ws;realtime.ws=null;try{ws?.close()}catch{}st.realtimeState='OFFLINE';
}
function scheduleRealtime(){if(realtime.stopped||realtime.timer||document.hidden||!st.token)return;realtime.timer=setTimeout(()=>{realtime.timer=null;connectRealtime()},Math.round(realtime.retry*(0.8+Math.random()*0.4)));realtime.retry=Math.min(30000,realtime.retry*2)}
function connectRealtime(){
 if(document.hidden||!st.token||typeof WebSocket==='undefined'||realtime.ws?.readyState===0||realtime.ws?.readyState===1)return;
 const base=realtimeBase();if(!base)return;realtime.stopped=false;
 try{
  const ws=new WebSocket(base.replace(/^http/,'ws')+'/api/realtime',['lotus-pos',st.token]);realtime.ws=ws;st.realtimeState='CONNECTING';
  ws.onopen=()=>{if(realtime.ws!==ws)return;realtime.retry=1000;st.realtimeState='ONLINE';realtime.lastPong=Date.now();if(realtime.ping)clearInterval(realtime.ping);wakeSync('state');realtime.ping=setInterval(()=>{if(realtime.ws!==ws)return;if(Date.now()-realtime.lastPong>60000){ws.close();return}try{ws.send('ping')}catch{ws.close()}},25000)};
  ws.onmessage=e=>{if(realtime.ws!==ws)return;if(e.data==='pong'){realtime.lastPong=Date.now();return}try{const m=JSON.parse(e.data);if(m.type==='invalidate')wakeSync(m.scope||'state',m.detail?.scopes)}catch{wakeSync('state')}};
  ws.onerror=()=>{try{ws.close()}catch{}};
  ws.onclose=()=>{if(realtime.ws!==ws)return;if(realtime.ping){clearInterval(realtime.ping);realtime.ping=null}realtime.ws=null;st.realtimeState='OFFLINE';scheduler.live.next=0;scheduler.service.next=0;scheduleRealtime()};
 }catch{st.realtimeState='OFFLINE';scheduleRealtime()}
}
if(typeof window.setInterval==='function')window.setInterval(schedulerTick,1000);if(typeof window.setInterval==='function')window.setInterval(()=>{if(!document.hidden)diag()},15000);
document.addEventListener('visibilitychange',()=>{if(document.hidden)closeRealtime();else{for(const task of Object.values(scheduler))task.next=0;schedulerTick();connectRealtime()}});
start().then(()=>{if(st.token){connectRealtime();schedulerTick()}});
